function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.grid}"/></svg>`}
const color=['blue','purple','teal','pink','green','amber'];
const nav=[['home','সকল সেবা'],['doctors','ডাক্তার'],['healthcare','স্বাস্থ্যসেবা'],['transport','পরিবহন'],['assistant','Kahaloo AI']];
let screen=new URLSearchParams(location.search).get('screen')||'home';
const allScreens=['home','assistant','doctors','healthcare','healthcare-categories','blood','technicians','education','transport'];if(!allScreens.includes(screen))screen='home';
const titles={home:'সকল সেবা',assistant:'Kahaloo AI',doctors:'ডাক্তার সেবা',healthcare:'স্বাস্থ্যসেবা','healthcare-categories':'স্বাস্থ্যসেবার ক্যাটাগরি',blood:'রক্ত সেবা',technicians:'মিস্ত্রি সেবা',education:'শিক্ষা সেবা',transport:'পরিবহন সেবা'};
function header(){return `<header class="topbar"><a class="brand" href="?screen=home"><span class="brandmark">${icon('leaf')}</span><span><span class="brandname">কাহালু স্মার্ট সেবা</span><span class="brandtag">KAHALOO SMART SEBA</span></span></a><nav class="topnav">${nav.map(([id,t])=>`<a class="navitem ${screen===id||screen==='healthcare-categories'&&id==='healthcare'?'active':''}" href="?screen=${id}">${t}</a>`).join('')}</nav><span class="location">${icon('pin')}কাহালু, বগুড়া</span><span class="avatar">KS</span></header>`}
function crumb(){return `<div class="crumb"><a href="?screen=home">হোম</a>${icon('chevron')}<span>সেবাসমূহ</span>${screen!=='home'?`${icon('chevron')}<span class="current">${titles[screen]}</span>`:''}</div>`}
function footer(){return `<footer class="footerstrip"><span><b>KAHALOO SMART SEBA</b> / PUBLIC WEB</span><span>UI CONCEPT · DEMO CONTENT</span><a href="index.html">CASE STUDY GALLERY</a></footer>`}
function hero(title,desc,word,ic1='pin',label1='সেবা খুঁজুন',ic2='chat',label2='সহায়তা নিন',extra=''){return `<section class="hero ${extra}"><div class="hero-content"><div class="eyebrow">${word}</div><h1>${title}</h1><p>${desc}</p></div><div class="hero-art"><div class="big-circle"></div><div class="small-circle"></div><div class="art-pin">${icon(ic1)}</div><div class="art-card a">${icon(ic1)}${label1}</div><div class="art-card b">${icon(ic2)}${label2}</div></div></section>`}
function search(label,cls=''){return `<div class="searchbar ${cls}">${icon('search')}<span>${label}</span><span class="searchbutton">খুঁজুন</span></div>`}
function sectionhead(title,desc='',cls=''){return `<div class="sectionhead ${cls}"><h2>${title}</h2><p>${desc}</p></div>`}
function cat(item,i,large=false){const [name,ic,sub,route]=item;return `<${route?'a':'div'} ${route?`href="?screen=${route}"`:''} class="${large?'category-large':'category-card'}"><span class="icon-box c-${color[i%color.length]}">${icon(ic)}</span><div>${large?`<h3>${name}</h3><p>${sub||'সেবার তথ্য ও যোগাযোগ'}</p>`:`<span class="category-title">${name}</span>`}</div></${route?'a':'div'}>`}
const homeCats=[['জরুরি সেবা','phone'],['ডাক্তার সেবা','doctor','', 'doctors'],['স্বাস্থ্যসেবা','heart','', 'healthcare'],['রক্ত সেবা','drop','', 'blood'],['বাসা ও ভাড়া','home'],['মিস্ত্রি সেবা','tools','', 'technicians'],['শিক্ষা সেবা','school','', 'education'],['পরিবহন সেবা','bus','', 'transport'],['সরকারি সেবা','bank'],['ইউনিয়ন সেবা','building'],['জমি ও সম্পত্তি','land'],['শ্রমিক সেবা','worker'],['প্রাণিসম্পদ','animal'],['কৃষি সেবা','plant'],['গৃহ সহায়তা','broom'],['লন্ড্রি','shirt'],['চাকরি','briefcase'],['মার্কেটপ্লেস','cart'],['লোন ও ব্যাংক','bank'],['ব্যবসা ও প্রতিষ্ঠান','store'],['আইনি সহায়তা','scales'],['রাইড বুকিং','bike'],['কুরিয়ার','truck'],['খাবার','food'],['ট্যুর ও পর্যটন','travel'],['ধর্মীয় সেবা','mosque'],['খবর ও নোটিশ','news'],['দর্শনীয় স্থান','mountain'],['স্বেচ্ছাসেবা','hand'],['পোষা প্রাণী','paw'],['হারানো ও পাওয়া','search'],['অনুষ্ঠান','calendar']];
function home(){return `<main class="main home-main">${hero('স্থানীয় সেবা, এখন এক জায়গায়।','কাহালুর প্রয়োজনীয় তথ্য, সেবাদাতা ও দৈনন্দিন সুযোগ সহজে খুঁজে নিন।','YOUR COMMUNITY. CONNECTED.','home','আপনার এলাকার সেবা','robot','Kahaloo AI','home-hero')}${search('কোন সেবা খুঁজছেন? যেমন: ডাক্তার, বাসা, মিস্ত্রি…','home-search')}${sectionhead('আপনার প্রয়োজনের বিভাগ বেছে নিন','স্বাস্থ্য, যাতায়াত, শিক্ষা ও আরও অনেক কিছু')}<div class="home-categories">${homeCats.map((c,i)=>cat(c,i)).join('')}</div><div class="home-lower"><div class="badge-icon">${icon('store')}</div><div><strong>আপনার সেবা এলাকার মানুষের কাছে পৌঁছে দিন</strong><p>স্থানীয় ব্যবসা ও সেবাদাতাদের জন্য একটি পরিচিতির জায়গা।</p></div><span class="btn light">সেবা যুক্ত করুন</span></div></main>`}
function side(selected){const opts=[['doctors','ডাক্তার খুঁজুন','doctor'],['healthcare','স্বাস্থ্যসেবা','hospital'],['healthcare-categories','সকল ক্যাটাগরি','grid'],['blood','রক্ত সেবা','drop'],['assistant','AI সহায়তা','robot']];return `<aside class="side-panel"><h3>স্বাস্থ্য ও সহায়তা</h3>${opts.map(([route,label,ic])=>`<a class="side-link ${selected===route?'selected':''}" href="?screen=${route}">${icon(ic)}${label}</a>`).join('')}<div class="side-divider"></div><div class="side-note"><strong>তথ্য থেকে যোগাযোগ</strong>প্রয়োজনের বিভাগ দেখুন, সেবাদাতার তথ্য জানুন এবং উপযুক্ত সেবার সঙ্গে যুক্ত হোন।</div></aside>`}
const healthCats=[['হাসপাতাল','hospital','হাসপাতালের তথ্য'],['ডায়াগনস্টিক','lab','পরীক্ষা কেন্দ্র'],['অ্যাম্বুলেন্স','ambulance','পরিবহন সহায়তা'],['ফার্মেসি','pill','ওষুধের দোকান'],['হোম কেয়ার','home','বাড়িতে সেবা'],['নার্সিং ও কেয়ার','nurse','পরিচর্যা সহায়তা'],['স্বাস্থ্য ক্যাম্প','tent','স্থানীয় কার্যক্রম'],['টিকাদান কেন্দ্র','syringe','কেন্দ্রের তথ্য']];
function provider(label,area,ic='doctor',booking=true){return `<article class="provider-card"><div class="provider-top"><span class="provider-portrait">${icon(ic)}</span><div><h3>${label}</h3><div class="meta">${area}</div></div><span class="sample-tag">DEMO</span></div><div class="provider-divider"></div><div class="detail-line">${icon('pin')}কাহালু, বগুড়া · নমুনা চেম্বার</div><div class="detail-line">${icon('calendar')}${booking?'সময় ও সিরিয়ালের তথ্য দেখুন':'সেবার ধরন ও যোগাযোগ দেখুন'}</div><div class="provider-actions"><span class="btn light small">বিস্তারিত দেখুন</span><span class="btn small">${booking?'সিরিয়াল দেখুন':'যোগাযোগ'}</span></div></article>`}
function doctors(){const specialties=[['মেডিসিন','doctor'],['শিশুরোগ','child'],['নারী ও প্রসূতি','person'],['হৃদরোগ','heart'],['অর্থোপেডিক','bone'],['চক্ষু','eye']];return `<main class="main">${crumb()}${hero('সঠিক বিশেষজ্ঞ খুঁজুন সহজে','বিশেষত্ব, চেম্বার ও সিরিয়ালের তথ্য দেখে সেবাদাতা বেছে নিন।','DOCTOR DISCOVERY','doctor','বিশেষজ্ঞের তথ্য','calendar','সিরিয়াল বুকিং','mini-hero')}<div class="section-layout">${side('doctors')}<div class="content-area">${search('বিশেষত্ব বা ডাক্তারের সেবা খুঁজুন…')}<div class="specialty-row">${specialties.map(([n,ic],i)=>`<div class="specialty ${i===0?'selected':''}"><span class="icon-box c-${color[i]}">${icon(ic)}</span>${n}</div>`).join('')}</div><div class="subsection-title"><h2>সেবাদাতা ও চেম্বার</h2><span>নমুনা পরিচিতি · ব্যক্তিগত তথ্য ব্যবহার করা হয়নি</span></div><div class="provider-row">${provider('নমুনা সেবাদাতা A','মেডিসিন সেবা')}${provider('নমুনা সেবাদাতা B','শিশুরোগ সেবা')}</div><div class="note-line">${icon('info')}সেবা নেওয়ার আগে চেম্বার ও সময়সূচির তথ্য নিশ্চিত করুন।</div></div></div></main>`}
function healthcare(){return `<main class="main">${crumb()}${hero('স্বাস্থ্যসেবার তথ্য হাতের কাছে','হাসপাতাল, পরীক্ষা কেন্দ্র, ফার্মেসি ও পরিচর্যার সেবা একসঙ্গে দেখুন।','HEALTHCARE DIRECTORY','hospital','প্রতিষ্ঠান খুঁজুন','heart','সেবার তথ্য','mini-hero')}<div class="section-layout">${side('healthcare')}<div class="content-area">${search('প্রতিষ্ঠান বা স্বাস্থ্যসেবার ধরন খুঁজুন…')}<div class="health-row">${healthCats.map((c,i)=>cat(c,i,true)).join('')}</div><div class="subsection-title"><h2>প্রতিষ্ঠানের পরিচিতি</h2><a class="small-link" href="?screen=healthcare-categories">সব ক্যাটাগরি দেখুন</a></div><div class="health-listings">${provider('নমুনা প্রতিষ্ঠান A','হাসপাতাল ও স্বাস্থ্যসেবা','hospital',false)}${provider('নমুনা প্রতিষ্ঠান B','ফার্মেসি ও সেবার তথ্য','pill',false)}</div></div></div></main>`}
function context(symbol,title,desc,points){return `<aside class="context-box"><div><span class="context-symbol">${icon(symbol)}</span><h2>${title}</h2><p>${desc}</p><ul>${points.map(p=>`<li>${icon('check')}${p}</li>`).join('')}</ul></div><div class="context-bottom">কাহালু স্মার্ট সেবা<br><span class="en">Local information. Useful connections.</span></div></aside>`}
function bottom(title,desc,button='সেবা যুক্ত করুন',ic='store'){return `<div class="category-bottom"><span class="icon-box c-green">${icon(ic)}</span><div><strong>${title}</strong><p>${desc}</p></div><span class="btn light">${button}</span></div>`}
function healthcareCategories(){return `<main class="main category-general health-categories">${crumb()}${hero('যে স্বাস্থ্যসেবা প্রয়োজন, সেটিই খুঁজুন','সেবার ধরন অনুযায়ী স্থানীয় প্রতিষ্ঠান ও প্রয়োজনীয় তথ্য দেখুন।','HEALTHCARE CATEGORIES','hospital','স্বাস্থ্যসেবা','lab','প্রতিষ্ঠানের তথ্য','mini-hero')}${search('স্বাস্থ্যসেবার ক্যাটাগরি খুঁজুন…','wide-search')}${sectionhead('স্বাস্থ্যসেবার বিভাগ','একই জায়গায় বিভিন্ন ধরনের সেবার পরিচিতি','compact-title')}<div class="category-grid-shell"><div class="category-large-grid">${healthCats.map((c,i)=>cat(c,i,true)).join('')}</div>${context('heart','যত্নের জন্য<br>প্রয়োজনীয় যোগাযোগ','আপনার প্রয়োজন অনুযায়ী স্বাস্থ্যসেবার বিভাগ বেছে নিন।',['প্রতিষ্ঠানের পরিচিতি','ঠিকানা ও যোগাযোগ','সেবার ধরন'])}</div>${bottom('আপনার স্বাস্থ্যসেবা প্রতিষ্ঠানের পরিচিতি যুক্ত করুন','এলাকার মানুষের কাছে প্রয়োজনীয় তথ্য পৌঁছে দিন।','প্রতিষ্ঠান যুক্ত করুন','hospital')}</main>`}
function blood(){const groups=['A+','A−','B+','B−','AB+','AB−','O+','O−'];return `<main class="main">${crumb()}${hero('রক্তদানের সংযোগ, মানুষের পাশে','রক্তের গ্রুপ অনুযায়ী স্থানীয় রক্তদাতার তথ্য খুঁজুন।','BLOOD DONOR DIRECTORY','drop','গ্রুপ অনুযায়ী খুঁজুন','hand','মানুষের পাশে','mini-hero blood-hero')}<div class="blood-layout"><div>${search('রক্তের গ্রুপ বা এলাকা খুঁজুন…')}${sectionhead('রক্তের গ্রুপ বেছে নিন','প্রয়োজন অনুযায়ী তথ্য দেখুন')}<div class="blood-groups">${groups.map((g,i)=>`<div class="blood-group ${i===0?'selected':''}">${icon('drop')}<b>${g}</b></div>`).join('')}</div><div class="subsection-title"><h2>রক্তদাতার পরিচিতি</h2><span>ডেমো তথ্য</span></div><div class="blood-list">${['A','B','C'].map((n,i)=>`<article class="donor-row"><span class="blood-type">A+</span><div><h3>নমুনা রক্তদাতা ${n}</h3><p>কাহালু, বগুড়া · ব্যক্তিগত যোগাযোগ গোপন</p></div><span class="sample-tag">DEMO</span><span class="btn light small">বিস্তারিত দেখুন</span></article>`).join('')}</div></div><aside class="blood-sidebar"><span class="icon-box c-pink">${icon('hand')}</span><h2>সহযোগিতার একটি সহজ পথ</h2><p>প্রয়োজনের তথ্য খুঁজে পেতে স্থানীয় রক্তদাতাদের সঙ্গে যোগাযোগের সুযোগ।</p><div class="step-list"><div class="step"><span class="step-symbol">${icon('drop')}</span><div><strong>গ্রুপ নির্বাচন করুন</strong><span>প্রয়োজনীয় রক্তের গ্রুপ বেছে নিন।</span></div></div><div class="step"><span class="step-symbol">${icon('search')}</span><div><strong>পরিচিতি দেখুন</strong><span>এলাকা ও প্রাসঙ্গিক তথ্য পড়ুন।</span></div></div><div class="step"><span class="step-symbol">${icon('phone')}</span><div><strong>যোগাযোগ নিশ্চিত করুন</strong><span>রক্তদাতার প্রাপ্যতা সরাসরি নিশ্চিত করুন।</span></div></div></div><div class="info-banner"><p>এখানে নমুনা পরিচিতি দেখানো হয়েছে। কোনো ব্যক্তিগত নম্বর প্রকাশ করা হয়নি।</p></div></aside></div></main>`}
