const transportCats=[['বাস ও কোচ','bus','দূরপাল্লা ও স্থানীয়'],['ট্রেন ও রেল','train','রেলযোগাযোগের তথ্য'],['CNG','car','স্থানীয় যাতায়াত'],['অটোরিকশা','car','এলাকাভিত্তিক পরিবহন'],['রিকশা','bike','স্বল্প দূরত্বের যাত্রা'],['কার ও মাইক্রোবাস','car','গাড়ির পরিচিতি'],['বাইক সেবা','bike','বাইক সেবার তথ্য'],['পণ্য পরিবহন','truck','পণ্য আনা-নেওয়া'],['স্টেশন ও স্ট্যান্ড','pin','যাত্রার স্থান খুঁজুন'],['রুট ও ভাড়া','route','যাতায়াতের তথ্য'],['বিশেষ পরিবহন','bus','বিশেষ প্রয়োজনের সেবা'],['অন্যান্য পরিবহন','road','আরও পরিবহন তথ্য']];
function transport(){return `<main class="main category-general transport-main">${crumb()}${hero('যাতায়াতের তথ্য হাতের কাছে','বাস, রেল ও স্থানীয় পরিবহনের পরিচিতি এক জায়গায় দেখুন।','TRANSPORT & MOBILITY','bus','যাত্রার তথ্য','route','স্থানীয় যোগাযোগ','mini-hero')}${search('যানবাহন, রুট বা স্ট্যান্ড খুঁজুন…','wide-search')}${sectionhead('কীভাবে যেতে চান?','পরিবহনের ধরন অনুযায়ী তথ্য দেখুন','compact-title')}<div class="category-grid-shell"><div class="category-large-grid transport-grid">${transportCats.map((c,i)=>cat(c,i,true)).join('')}</div>${context('route','যাত্রার আগে<br>প্রয়োজনীয় তথ্য','পরিবহন বেছে নেওয়ার আগে প্রাসঙ্গিক যোগাযোগ ও রুটের তথ্য দেখে নিন।',['পরিবহনের ধরন','স্টেশন ও স্ট্যান্ড','রুট ও ভাড়ার তথ্য','সেবাদাতার যোগাযোগ'])}</div>${bottom('আপনার পরিবহন সেবার পরিচিতি যুক্ত করুন','স্থানীয় যাত্রীদের কাছে প্রয়োজনীয় তথ্য পৌঁছে দিন।','সেবা যুক্ত করুন','bus')}</main>`}
function assistant(){return `<main class="main ai-main">${crumb()}<div class="ai-shell"><aside class="ai-sidebar"><div class="ai-label">YOUR LOCAL ASSISTANT</div><h2>কী খুঁজছেন<br>কাহালুতে?</h2><p>এলাকার প্রয়োজনীয় সেবা খুঁজে পাওয়ার পথে সহজ সহায়তা।</p><div class="ai-topics"><div class="ai-topic">${icon('phone')}জরুরি যোগাযোগ</div><div class="ai-topic">${icon('doctor')}ডাক্তার ও হাসপাতাল</div><div class="ai-topic">${icon('bus')}যাতায়াতের তথ্য</div><div class="ai-topic">${icon('home')}বাসা ও ভাড়া</div><div class="ai-topic">${icon('tools')}মিস্ত্রি ও স্থানীয় সেবা</div></div><div class="ai-sidebar-footer">এটি নমুনা কথোপকথন।<br>সেবার তথ্য সংশ্লিষ্ট প্রতিষ্ঠানের সঙ্গে নিশ্চিত করুন।</div></aside><section class="ai-chat"><header class="ai-chathead"><div class="ai-icon">${icon('robot')}</div><div><h1>Kahaloo AI</h1><p>কাহালু স্মার্ট সেবার ডিজিটাল সহকারী</p></div><div class="ai-tools"><span class="ai-tool">${icon('speaker')}</span><span class="ai-tool">${icon('refresh')}</span></div></header><div class="conversation"><div class="chat-line"><span class="chat-avatar">${icon('robot')}</span><div class="bubble"><strong>আসসালামু আলাইকুম!</strong><p>কাহালুর প্রয়োজনীয় তথ্য ও সেবা খুঁজতে সাহায্য করতে পারি।<br>আপনি কোন ধরনের সেবা খুঁজছেন?</p></div></div><div class="chat-line user"><div class="bubble">কাহালুতে হাসপাতালের তথ্য কোথায় পাব?</div></div><div class="chat-line"><span class="chat-avatar">${icon('robot')}</span><div class="bubble"><p>স্বাস্থ্যসেবা বিভাগে হাসপাতাল ও সংশ্লিষ্ট প্রতিষ্ঠানের পরিচিতি দেখতে পারেন। কোন বিভাগটি দেখতে চান?</p><div class="response-options"><a href="?screen=healthcare"><span>হাসপাতাল</span></a><span>ডায়াগনস্টিক</span><span>অ্যাম্বুলেন্স</span><a href="?screen=doctors"><span>ডাক্তার</span></a></div></div></div><div class="chat-sample">ILLUSTRATIVE CONVERSATION</div></div><div class="composer"><div class="composer-box">${icon('mic')}<span>কাহালুর কোন সেবা খুঁজছেন? লিখুন…</span><span class="send">${icon('send')}</span></div><div class="composer-note">এই প্রদর্শনীতে কোনো তথ্য পাঠানো বা সংরক্ষণ করা হয় না।</div></div></section></div></main>`}
const views={home,assistant,doctors,healthcare,'healthcare-categories':healthcareCategories,blood,technicians,education,transport};
document.getElementById('artboard').innerHTML=header()+views[screen]()+footer();
document.title=`${titles[screen]} · KSS Web UI Concept`;

